        _ = &self;
            if (Environment.isPosix) {
                const act = bun.sys.Sigaction{ .handler = .{ .sigaction = posixHandler }, .mask = bun.sys.sigemptyset(), .flags = std.posix.SA.SIGINFO };
                _ = bun.sys.sigaction(std.posix.SIG.INT, (&act), (&abort_prev_int));
                _ = bun.sys.sigaction(std.posix.SIG.TERM, (&act), (&abort_prev_term));
            } else {
                _ = bun.c.SetConsoleCtrlHandler(windowsCtrlHandler, std.os.windows.TRUE);
            }
    }

pub fn uninstall(self: CoordinatorAbortHandler) void {
        _ = &self;
            if (Environment.isPosix) {
                _ = bun.sys.sigaction(std.posix.SIG.INT, (&abort_prev_int), null);
                _ = bun.sys.sigaction(std.posix.SIG.TERM, (&abort_prev_term), null);
            } else {
                _ = bun.c.SetConsoleCtrlHandler(windowsCtrlHandler, std.os.windows.FALSE);
            }
    }
    pub const should_abort = &abort_should_abort;
};

const string = []const u8;
